using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(menuName = "Variables References/Astrea/Star Ability Reference")]
public class StarAbilityReference : ScriptableObject
{
	[Header("Variable")]
	[SerializeField]
	private bool externalSet;

	[SerializeField]
	[HideIf("externalSet")]
	private StarAbility value;

	public StarAbility Value => value;

	public void SetValue(StarAbility value)
	{
		if (externalSet)
		{
			this.value = value;
		}
		else
		{
			Debug.Log($"Cannot set {base.name} from external source, because bool externalSet is false");
		}
	}
}
